def cancel_pending_order(order_id, reason, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0041000" if __import__("os").path.isdir("./environment_mix/0041000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_audit_and_rate(endpoint, started, status=None):
        """
        Minimal observable dynamics:
        - Ensure /app/database/audit_log.json exists and append one row per call.
        - Enforce a simple rolling per-minute rate limit based on audit_log.json.
        """
        audit_file = "audit_log.json"
        audit = _load(audit_file)
        if not isinstance(audit, list):
            audit = []
        now_ts = _now()

        # rate limit: 120 requests/minute overall
        window_s = 60
        limit = 120
        try:
            now_dt = datetime.datetime.utcnow()
            cutoff = now_dt - datetime.timedelta(seconds=window_s)
            recent = 0
            for r in audit:
                ts = r.get("ts")
                if not isinstance(ts, str):
                    continue
                try:
                    rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if rdt >= cutoff:
                    recent += 1
            if recent >= limit:
                # log the denied request
                latency_ms = int((time.time() - started) * 1000)
                audit.append({"ts": now_ts, "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": latency_ms})
                _save(audit_file, audit)
                return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit_per_minute=limit)
        except Exception:
            # If audit parsing fails, still proceed but do not block the call.
            pass
        return None

    started = time.time()
    endpoint = "cancel_pending_order"

    # validate inputs
    if not isinstance(order_id, str) or not order_id or not order_id.startswith("#"):
        rl = _ensure_audit_and_rate(endpoint, started)
        if rl:
            return rl
        # log validation error
        audit = _load("audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({"ts": _now(), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - started) * 1000)})
        _save("audit_log.json", audit)
        return _err("VALIDATION_ERROR", "order_id must be a non-empty string starting with '#'.")
    if not isinstance(reason, str) or reason not in ("no longer needed", "ordered by mistake"):
        rl = _ensure_audit_and_rate(endpoint, started)
        if rl:
            return rl
        audit = _load("audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({"ts": _now(), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - started) * 1000)})
        _save("audit_log.json", audit)
        return _err("VALIDATION_ERROR", "reason must be one of: 'no longer needed', 'ordered by mistake'.")

    rl = _ensure_audit_and_rate(endpoint, started)
    if rl:
        return rl

    orders = _load("orders.json")
    users = _load("users.json")

    if not isinstance(orders, list):
        orders = []
    if not isinstance(users, list):
        users = []

    order = None
    order_idx = None
    for i, o in enumerate(orders):
        if isinstance(o, dict) and o.get("order_id") == order_id:
            order = o
            order_idx = i
            break

    if order is None:
        audit = _load("audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({"ts": _now(), "endpoint": endpoint, "status": "NOT_FOUND", "latency_ms": int((time.time() - started) * 1000)})
        _save("audit_log.json", audit)
        return _err("NOT_FOUND", "Order not found.", order_id=order_id)

    if order.get("status") != "pending":
        audit = _load("audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({"ts": _now(), "endpoint": endpoint, "status": "INVALID_TRANSITION", "latency_ms": int((time.time() - started) * 1000)})
        _save("audit_log.json", audit)
        return _err("INVALID_TRANSITION", "Only pending orders can be cancelled.", current_status=order.get("status"))

    # perform cancellation + refunds in payment_history (ledger). Also adjust gift card balance if applicable.
    payment_history = order.get("payment_history")
    if payment_history is None:
        payment_history = []
        order["payment_history"] = payment_history
    if not isinstance(payment_history, list):
        audit = _load("audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({"ts": _now(), "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time() - started) * 1000)})
        _save("audit_log.json", audit)
        return _err("VALIDATION_ERROR", "Order payment_history is invalid.")

    user_id = order.get("user_id")
    user = None
    user_idx = None
    if isinstance(user_id, str):
        for i, u in enumerate(users):
            if isinstance(u, dict) and u.get("user_id") == user_id:
                user = u
                user_idx = i
                break

    # Sum payments already made to refund them; ignore prior refunds.
    refunds_to_add = []
    for tx in payment_history:
        if not isinstance(tx, dict):
            continue
        if tx.get("transaction_type") != "payment":
            continue
        amt = tx.get("amount")
        pmid = tx.get("payment_method_id")
        if not isinstance(amt, (int, float)) or not isinstance(pmid, str) or amt <= 0:
            continue
        refunds_to_add.append({"transaction_type": "refund", "amount": float(amt), "payment_method_id": pmid})

        # If it was a gift card payment, credit it back immediately if we can locate it
        if user is not None:
            pms = user.get("payment_methods")
            if isinstance(pms, list):
                for pm in pms:
                    if isinstance(pm, dict) and pm.get("id") == pmid and pm.get("source") == "gift_card":
                        bal = pm.get("balance", 0.0)
                        if isinstance(bal, (int, float)):
                            pm["balance"] = round(float(bal) + float(amt), 2)
                        break

    order["status"] = "cancelled"
    order["cancel_reason"] = reason
    order["cancelled_at"] = _now()
    if refunds_to_add:
        order["payment_history"] = payment_history + refunds_to_add

    # persist order (and user if modified)
    orders[order_idx] = order
    _save("orders.json", orders)
    if user is not None and user_idx is not None:
        users[user_idx] = user
        _save("users.json", users)

    audit = _load("audit_log.json")
    if not isinstance(audit, list):
        audit = []
    audit.append({"ts": _now(), "endpoint": endpoint, "status": "OK", "latency_ms": int((time.time() - started) * 1000)})
    _save("audit_log.json", audit)

    return {"order": order}

