            audit = []
        try:
            now_dt = datetime.datetime.utcnow()
            cutoff = now_dt - datetime.timedelta(seconds=60)
            recent = 0
            for r in audit:
                ts = r.get("ts")
                if not isinstance(ts, str):
                    continue
                try:
                    rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if rdt >= cutoff:
                    recent += 1
            if recent >= 120:
                _log(endpoint, started, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit_per_minute=120)
        except Exception:
            pass
        return None

    started = time.time()
    endpoint = "modify_pending_order_items"

    if not isinstance(order_id, str) or not order_id or not order_id.startswith("#"):
        rl = _rate_limit(endpoint, started)
        if rl:
            return rl
        _log(endpoint, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_id must be a non-empty string starting with '#'.")
    if not isinstance(item_ids, list) or not all(isinstance(x, str) and x for x in item_ids):
        rl = _rate_limit(endpoint, started)
        if rl:
            return rl
        _log(endpoint, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "item_ids must be an array of strings.")
    if not isinstance(new_item_ids, list) or not all(isinstance(x, str) and x for x in new_item_ids):
        rl = _rate_limit(endpoint, started)
        if rl:
            return rl
        _log(endpoint, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "new_item_ids must be an array of strings.")
    if len(item_ids) != len(new_item_ids):
        rl = _rate_limit(endpoint, started)
        if rl:
            return rl
        _log(endpoint, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "item_ids and new_item_ids must have the same length.")
    if not isinstance(payment_method_id, str) or not payment_method_id.strip():
        rl = _rate_limit(endpoint, started)
        if rl:
            return rl
        _log(endpoint, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "payment_method_id is required.")

    rl = _rate_limit(endpoint, started)
    if rl:
        return rl

    orders = _load("orders.json")
    users = _load("users.json")
    products = _load("products.json")
    if not isinstance(orders, list):
        orders = []
    if not isinstance(users, list):
        users = []
    if not isinstance(products, list):
        products = []

    # build product lookup product_id -> product row
    prod_by_id = {}
    for p in products:
        if isinstance(p, dict) and isinstance(p.get("product_id"), str):
            prod_by_id[p["product_id"]] = p

    order = None
    oidx = None
    for i, o in enumerate(orders):
        if isinstance(o, dict) and o.get("order_id") == order_id:
            order = o
            oidx = i
            break
    if order is None:
        _log(endpoint, started, "NOT_FOUND")
        return _err("NOT_FOUND", "Order not found.", order_id=order_id)
    if order.get("status") != "pending":
        _log(endpoint, started, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Only pending orders can be modified.", current_status=order.get("status"))

    user_id = order.get("user_id")
    user = None
    for u in users:
        if isinstance(u, dict) and u.get("user_id") == user_id:
            user = u
            break
    if user is None:
        _log(endpoint, started, "NOT_FOUND")
        return _err("NOT_FOUND", "User for order not found.", user_id=user_id)

    # payment method availability check
    pm = None
    pms = user.get("payment_methods")
    if isinstance(pms, list):
        for m in pms:
            if isinstance(m, dict) and m.get("id") == payment_method_id:
                pm = m
                break
    if pm is None:
        _log(endpoint, started, "NOT_FOUND")
        return _err("NOT_FOUND", "Payment method not found for user.", payment_method_id=payment_method_id)

    items = order.get("items")
    if not isinstance(items, list):
        _log(endpoint, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Order items are invalid.")

    # verify we can replace each requested item occurrence and compute diff
    # We'll replace by first unmatched occurrence for each old item_id.
    indices_by_item_id = {}
    for idx, it in enumerate(items):
        if isinstance(it, dict) and isinstance(it.get("item_id"), str):
            indices_by_item_id.setdefault(it["item_id"], []).append(idx)

    used_index = set()
    replacements = []  # tuples (old_index, new_item_row)
    diff = 0.0

    # helper: find variant row in product variants (variants may be list or dict-ish)
    def _find_variant(product_row, item_id_value):
        vars_ = product_row.get("variants")
        if isinstance(vars_, list):
            for v in vars_:
                if isinstance(v, dict) and v.get("item_id") == item_id_value:
                    return v
        elif isinstance(vars_, dict):
            # tolerate dict keyed by item_id
            v = vars_.get(item_id_value)
            if isinstance(v, dict):
                if "item_id" not in v:
                    v = dict(v)
                    v["item_id"] = item_id_value
                return v
        return None

    for old_id, new_id in zip(item_ids, new_item_ids):
        cand = indices_by_item_id.get(old_id, [])
        chosen = None
        for j in cand:
            if j not in used_index:
                chosen = j
                break
        if chosen is None:
            _log(endpoint, started, "NOT_FOUND")
            return _err("NOT_FOUND", "One or more item_ids were not found on the order.", item_id=old_id)

        old_item = items[chosen]
        if not isinstance(old_item, dict) or old_item.get("item_id") != old_id:
            _log(endpoint, started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Order item data is malformed.")

        prod_id = old_item.get("product_id")
        if not isinstance(prod_id, str) or prod_id not in prod_by_id:
            _log(endpoint, started, "NOT_FOUND")
            return _err("NOT_FOUND", "Product for order item not found.", product_id=prod_id)

        product_row = prod_by_id[prod_id]
        new_variant = _find_variant(product_row, new_id)
        if new_variant is None:
            _log(endpoint, started, "NOT_FOUND")
            return _err("NOT_FOUND", "Replacement item_id not found for that product.", new_item_id=new_id, product_id=prod_id)

        if new_variant.get("available") is not True:
            _log(endpoint, started, "CONFLICT")
            return _err("CONFLICT", "Replacement item is not available.", new_item_id=new_id)

        old_price = old_item.get("price")
        new_price = new_variant.get("price")
        if not isinstance(old_price, (int, float)) or not isinstance(new_price, (int, float)):
            _log(endpoint, started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Item price data is invalid.")

        diff += float(new_price) - float(old_price)

        # Build new order item, keeping name/product_id/options from variant if present, else from old_item
        new_item = dict(old_item)
        new_item["item_id"] = new_id
        new_item["price"] = float(new_price)
        # options may be stored under variant["options"]
        if isinstance(new_variant.get("options"), dict):
            new_item["options"] = new_variant["options"]
        used_index.add(chosen)
        replacements.append((chosen, new_item))

    # handle charge/refund against payment method (gift card balance enforced)
    diff = round(diff, 2)
    if diff != 0:
        if pm.get("source") == "gift_card":
            bal = pm.get("balance", 0.0)
            if not isinstance(bal, (int, float)):
                _log(endpoint, started, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Gift card balance is invalid.")
            if diff > 0 and float(bal) < diff:
                _log(endpoint, started, "CONFLICT")
                return _err("CONFLICT", "Insufficient gift card balance to cover price difference.", required=diff, balance=float(bal))
            # apply balance change
            if diff > 0:
                pm["balance"] = round(float(bal) - diff, 2)
            else:
                pm["balance"] = round(float(bal) + abs(diff), 2)

        ph = order.get("payment_history")
        if ph is None:
            ph = []
            order["payment_history"] = ph
        if not isinstance(ph, list):
            _log(endpoint, started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Order payment_history is invalid.")
        order["payment_history"].append(
            {
                "transaction_type": "payment" if diff > 0 else "refund",
                "amount": abs(diff),
                "payment_method_id": payment_method_id,
            }
        )

    # apply replacements
    for idx, new_item in replacements:
        items[idx] = new_item
    order["items"] = items
    order["updated_at"] = _now()

    orders[oidx] = order
    _save("orders.json", orders)
    _save("users.json", users)  # persist possible gift card balance change

    _log(endpoint, started, "OK")
    return {"order": order, "price_difference": diff, "payment_method_id": payment_method_id}

def modify_pending_order_payment(order_id, payment_method_id, **_extra):
