                except Exception:
                    continue
                if rdt >= cutoff:
                    recent += 1
            if recent >= 120:
                _log(endpoint, started, "RATE_LIMIT")
                return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit_per_minute=120)
        except Exception:
            pass
        return None

    started = time.time()
    endpoint = "modify_pending_order_payment"

    if not isinstance(order_id, str) or not order_id or not order_id.startswith("#"):
        rl = _rate_limit(endpoint, started)
        if rl:
            return rl
        _log(endpoint, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order_id must be a non-empty string starting with '#'.")
    if not isinstance(payment_method_id, str) or not payment_method_id.strip():
        rl = _rate_limit(endpoint, started)
        if rl:
            return rl
        _log(endpoint, started, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "payment_method_id is required.")

    rl = _rate_limit(endpoint, started)
    if rl:
        return rl

    orders = _load("orders.json")
    users = _load("users.json")
    if not isinstance(orders, list):
        orders = []
    if not isinstance(users, list):
        users = []

    order = None
    oidx = None
    for i, o in enumerate(orders):
        if isinstance(o, dict) and o.get("order_id") == order_id:
            order = o
            oidx = i
            break
    if order is None:
        _log(endpoint, started, "NOT_FOUND")
        return _err("NOT_FOUND", "Order not found.", order_id=order_id)
    if order.get("status") != "pending":
        _log(endpoint, started, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Only pending orders can be modified.", current_status=order.get("status"))

    user_id = order.get("user_id")
    user = None
    for u in users:
        if isinstance(u, dict) and u.get("user_id") == user_id:
            user = u
            break
    if user is None:
        _log(endpoint, started, "NOT_FOUND")
        return _err("NOT_FOUND", "User for order not found.", user_id=user_id)

    # payment method must exist
    new_pm = None
    pms = user.get("payment_methods")
    if isinstance(pms, list):
        for pm in pms:
            if isinstance(pm, dict) and pm.get("id") == payment_method_id:
                new_pm = pm
                break
    if new_pm is None:
        _log(endpoint, started, "NOT_FOUND")
        return _err("NOT_FOUND", "Payment method not found for user.", payment_method_id=payment_method_id)

    ph = order.get("payment_history")
    if not isinstance(ph, list) or not ph:
        _log(endpoint, started, "CONFLICT")
        return _err("CONFLICT", "Order has no payment history to update.")

    # Determine current paid amount as net payments-refunds, but for pending assume initial payment exists.
    net = 0.0
    for tx in ph:
        if not isinstance(tx, dict):
            continue
        amt = tx.get("amount")
        ttype = tx.get("transaction_type")
        if not isinstance(amt, (int, float)) or ttype not in ("payment", "refund"):
            continue
        net += float(amt) if ttype == "payment" else -float(amt)
    net = round(net, 2)
    if net <= 0:
        _log(endpoint, started, "CONFLICT")
        return _err("CONFLICT", "No outstanding paid amount found to migrate.", net_paid=net)

    # Identify "current payment method" as the most recent payment's payment_method_id
    current_pmid = None
    for tx in reversed(ph):
        if isinstance(tx, dict) and tx.get("transaction_type") == "payment" and isinstance(tx.get("payment_method_id"), str):
            current_pmid = tx["payment_method_id"]
            break
    if current_pmid is None:
        _log(endpoint, started, "CONFLICT")
        return _err("CONFLICT", "Cannot determine current payment method.")
    if current_pmid == payment_method_id:
        _log(endpoint, started, "CONFLICT")
        return _err("CONFLICT", "New payment method must be different from current payment method.", payment_method_id=payment_method_id)

    # If new method is gift card, must have enough balance to cover net
    if new_pm.get("source") == "gift_card":
        bal = new_pm.get("balance", 0.0)
        if not isinstance(bal, (int, float)):
            _log(endpoint, started, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Gift card balance is invalid.")
        if float(bal) < net:
            _log(endpoint, started, "CONFLICT")
            return _err("CONFLICT", "Insufficient gift card balance to pay for the order.", required=net, balance=float(bal))
        new_pm["balance"] = round(float(bal) - net, 2)

    # If current method was a gift card, refund it (credit balance)
    if isinstance(pms, list) and isinstance(current_pmid, str):
        for pm in pms:
            if isinstance(pm, dict) and pm.get("id") == current_pmid and pm.get("source") == "gift_card":
                bal = pm.get("balance", 0.0)
                if isinstance(bal, (int, float)):
                    pm["balance"] = round(float(bal) + net, 2)
                break

    # Append ledger entries
    ph.append({"transaction_type": "refund", "amount": net, "payment_method_id": current_pmid})
    ph.append({"transaction_type": "payment", "amount": net, "payment_method_id": payment_method_id})
    order["payment_history"] = ph
    order["updated_at"] = _now()

    orders[oidx] = order
    _save("orders.json", orders)
    _save("users.json", users)

    _log(endpoint, started, "OK")
    return {"order": order, "migrated_amount": net, "from_payment_method_id": current_pmid, "to_payment_method_id": payment_method_id}

