        return _err("VALIDATION_ERROR", "summary is required.")

    # rate limit (120/min)
    audit = _load("audit_log.json")
    if not isinstance(audit, list):
        audit = []
    try:
        now_dt = datetime.datetime.utcnow()
        cutoff = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for r in audit:
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                rdt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if rdt >= cutoff:
                recent += 1
        if recent >= 120:
            audit.append({"ts": _now(), "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": int((time.time() - started) * 1000)})
            _save("audit_log.json", audit)
            return _err("RATE_LIMIT", "Too many requests. Please retry later.", limit_per_minute=120)
    except Exception:
        pass

    # persist a handoff record (observable effect)
    handoffs = _load("human_handoffs.json")
    if not isinstance(handoffs, list):
        handoffs = []
    handoff_id = "hh_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + "_" + str(len(handoffs) + 1)
    row = {
        "handoff_id": handoff_id,
        "ts": _now(),
        "status": "queued",
        "summary": summary.strip(),
    }
    handoffs.append(row)
    _save("human_handoffs.json", handoffs)

    audit.append({"ts": _now(), "endpoint": endpoint, "status": "OK", "latency_ms": int((time.time() - started) * 1000), "handoff_id": handoff_id})
    _save("audit_log.json", audit)

    return {"handoff": row, "message": "Conversation escalated to a human agent."}
